"""Play chosen practice cases N times with the worktree's buyer, waiting for a free slot while the
team key is at its open-session limit. Usage: run.py P08,P18,P10 3 TAG"""

import logging
import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor

from arena_kit import ArenaClient, ArenaError
from arena_kit.cli import load_env
from arena_kit.play import hosted

from buyer import llm, runner
from buyer.cli import load_package

load_env()
wanted, reps, tag = sys.argv[1].split(","), int(sys.argv[2]), sys.argv[3]
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s", datefmt="%H:%M:%S")
client = ArenaClient()
pkg = load_package(os.environ.get("ARENA_DATA"))
complete = llm.complete_from_env()
files = {c["case_id"].split(":")[-1]: c for c in hosted(client.cases("practice"))}


def one(cid):
    for _ in range(60):
        try:
            table = runner.PracticeTable(client, files[cid])
            return runner.play_case(table, files[cid]["case_id"], pkg, complete=complete)
        except ArenaError as e:
            if e.status == 429 and "open sessions" in str(e.detail):
                time.sleep(20)
                continue
            return e
    return RuntimeError("no free session slot in 20 minutes")


for r in range(reps):
    with ThreadPoolExecutor(len(wanted)) as pool:
        out = list(pool.map(one, wanted))
    for cid, res in zip(wanted, out, strict=True):
        shown = res if isinstance(res, Exception) else {k: res.get(k) for k in ("deal", "score")}
        print(f"RESULT {tag} rep={r + 1} {cid} {shown}", flush=True)

